# --- Seed data. Codes are stable identifiers; names are display labels; list order is display order. ---

# (code, name, unit) in funnel order. CONVERSIONS is what Google and Microsoft Ads report.
OUTCOME_METRICS = [
    ("IMPRESSIONS", "Impressions", "COUNT"),
    ("CLICKS", "Clicks", "COUNT"),
    ("VISITORS", "Visitors", "COUNT"),
    ("ENGAGEMENTS", "Engagements", "COUNT"),
    ("LEADS", "Leads", "COUNT"),
    ("FOLLOW_UPS", "Follow-ups", "COUNT"),
    ("MQLS", "MQLs", "COUNT"),
    ("SQLS", "SQLs", "COUNT"),
    ("TRIALS", "Trials", "COUNT"),
    ("DEMOS", "Demos", "COUNT"),
    ("CONVERSIONS", "Conversions", "COUNT"),
    ("CUSTOMERS", "Customers", "COUNT"),
    ("PIPELINE", "Pipeline", "MONEY"),
    ("REVENUE", "Revenue", "MONEY"),
]

# The CEO asked for cost per visitor, demo and follow-up; the original KPI list had none of them.
# (code, name, sort order) — placed beside the cost-per KPIs they belong with
NEW_KPIS = [
    ("CP_VISITOR", "CP-Visitor", 45),
    ("CP_FOLLOW_UP", "CP-Follow-up", 55),
    ("CP_DEMO", "CP-Demo", 85),
]

# Proposed defaults per sub-channel, to confirm with Marketing: (sub-channel, funnel stage, goal, KPI, maturity days)
EVALUATION_DEFAULTS = [
    ("IN_PERSON_EVENTS", "CONVERSION", "DEMOS", "CP_DEMO", 180),
    ("SPONSORSHIPS", "CONSIDERATION", "LEADS", "CPL", 180),
    ("VIRTUAL_EVENTS", "CONSIDERATION", "LEADS", "CPL", 90),
    ("WEBINARS", "CONSIDERATION", "LEADS", "CPL", 90),
    ("GOOGLE_ADS", "CONSIDERATION", "LEADS", "CPL", 90),
    ("BING_ADS", "CONSIDERATION", "LEADS", "CPL", 90),
]


def _seed() -> None:
    op.bulk_insert(
        sa.table("outcome_metrics", sa.column("code"), sa.column("name"), sa.column("unit"), sa.column("sort_order")),
        [{"code": c, "name": n, "unit": u, "sort_order": (i + 1) * 10} for i, (c, n, u) in enumerate(OUTCOME_METRICS)],
    )
    op.bulk_insert(
        sa.table("primary_kpis", sa.column("code"), sa.column("name"), sa.column("sort_order")),
        [{"code": c, "name": n, "sort_order": order} for c, n, order in NEW_KPIS],
    )
    columns = list(zip(*EVALUATION_DEFAULTS))
    op.get_bind().execute(
        sa.text("""
            INSERT INTO evaluation_defaults (sub_channel_id, funnel_stage_id, goal_id, primary_kpi_id, maturity_days)
            SELECT sc.id, fs.id, g.id, k.id, d.maturity_days
            FROM unnest(CAST(:subs AS text[]), CAST(:stages AS text[]), CAST(:goals AS text[]), CAST(:kpis AS text[]),
                        CAST(:days AS int[])) AS d(sub_channel, stage, goal, kpi, maturity_days)
            JOIN sub_channels sc ON sc.code = d.sub_channel
            JOIN funnel_stages fs ON fs.code = d.stage
            JOIN goals g ON g.code = d.goal AND g.funnel_stage_id = fs.id
            JOIN primary_kpis k ON k.code = d.kpi
        """),
        {"subs": list(columns[0]), "stages": list(columns[1]), "goals": list(columns[2]), "kpis": list(columns[3]),
         "days": list(columns[4])},
    )
